Date: Thu, 29 Oct 2026 15:06:47 +0100
Subject: [PATCH] applets/digital-clock: Keep AM/PM where the locale puts it

The clock rebuilt its time format as hours, minutes and " AP", so AM/PM
always came after the time, even in Korean where it comes first. Edit
the locale's own format instead, changing only its hours and seconds.

BUG: 408662
---
 applets/digital-clock/DigitalClock.qml      |  41 +------
 applets/digital-clock/plugin/CMakeLists.txt |   2 +
 applets/digital-clock/plugin/timeformat.cpp | 126 ++++++++++++++++++++
 applets/digital-clock/plugin/timeformat.h   |  33 +++++
 4 files changed, 164 insertions(+), 38 deletions(-)
 create mode 100644 applets/digital-clock/plugin/timeformat.cpp
 create mode 100644 applets/digital-clock/plugin/timeformat.h

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..febc8b5189 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -511,44 +511,9 @@ MouseArea {
         font.italic: timeLabel.font.italic
     }

-    // Qt's QLocale does not offer any modular time creating like Klocale did
-    // eg. no "gimme time with seconds" or "gimme time without seconds and with time zone".
-    // QLocale supports only two formats - Long and Short. Long is unusable in many situations
-    // and Short does not provide seconds. So if seconds are enabled, we need to add it here.
-    //
-    // What happens here is that it looks for the delimiter between "h" and "m", takes it
-    // and appends it after "mm" and then appends "ss" for the seconds.
-    function timeFormatCorrection(timeFormatString = Qt.locale().timeFormat(Locale.ShortFormat)) {
-        const regexp = /(hh*)(.+)(mm)/i
-        const match = regexp.exec(timeFormatString);
-
-        const hours = match[1];
-        const delimiter = match[2];
-        const minutes = match[3]
-        const seconds = "ss";
-        const amPm = "AP";
-        const uses24hFormatByDefault = timeFormatString.toLowerCase().indexOf("ap") === -1;
-
-        // because QLocale is incredibly stupid and does not convert 12h/24h clock format
-        // when uppercase H is used for hours, needs to be h or hh, so toLowerCase()
-        let hoursFormat = hours.toLowerCase();
-        // A 12h locale has no convention for 24h times to follow, so when the 24h
-        // format is forced, use the common zero-padded hours (00:27, not 0:27)
-        if (Plasmoid.configuration.use24hFormat === Qt.Checked && !uses24hFormatByDefault) {
-            hoursFormat = "hh";
-        }
-        let result = hoursFormat + delimiter + minutes;
-
-        let result_sec = result + delimiter + seconds;
-
-        // add "AM/PM" either if the setting is the default and locale uses it OR if the user unchecked "use 24h format"
-        if ((Plasmoid.configuration.use24hFormat === Qt.PartiallyChecked && !uses24hFormatByDefault) || Plasmoid.configuration.use24hFormat === Qt.Unchecked) {
-            result += " " + amPm;
-            result_sec += " " + amPm;
-        }
-
-        timeFormat = result;
-        timeFormatWithSeconds = result_sec;
+    function timeFormatCorrection() {
+        timeFormat = TimeFormat.clockFormat(Plasmoid.configuration.use24hFormat, false);
+        timeFormatWithSeconds = TimeFormat.clockFormat(Plasmoid.configuration.use24hFormat, true);
         setupLabels();
     }

