diff --git a/applets/digital-clock/plugin/timeformat.cpp b/applets/digital-clock/plugin/timeformat.cpp
new file mode 100644
index 0000000000..c4a3b8381b
--- /dev/null
+++ b/applets/digital-clock/plugin/timeformat.cpp
@@ -0,0 +1,126 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "timeformat.h"
+
+#include <QLocale>
+
+using namespace Qt::StringLiterals;
+
+namespace
+{
+// Position of the first field made of one of chars at or after from, skipping 'quoted text', or -1
+qsizetype findField(QStringView format, QLatin1StringView chars, qsizetype from = 0)
+{
+    bool quoted = false;
+    for (qsizetype i = 0; i < format.size(); ++i) {
+        if (format[i] == u'\'') {
+            quoted = !quoted;
+        } else if (!quoted && i >= from && chars.contains(format[i])) {
+            return i;
+        }
+    }
+    return -1;
+}
+
+qsizetype fieldEnd(QStringView format, qsizetype pos)
+{
+    qsizetype end = pos;
+    while (end < format.size() && format[end] == format[pos]) {
+        ++end;
+    }
+    return end;
+}
+}
+
+TimeFormat::TimeFormat(QObject *parent)
+    : QObject(parent)
+{
+}
+
+QString TimeFormat::clockFormat(int use24hFormat, bool withSeconds)
+{
+    const QString format = withHourCycle(QLocale().timeFormat(QLocale::ShortFormat), Qt::CheckState(use24hFormat));
+    return TimeFormat::withSeconds(format, withSeconds);
+}
+
+QString TimeFormat::withHourCycle(const QString &format, Qt::CheckState use24hFormat)
+{
+    QString result = format;
+    const qsizetype amPm = findField(result, "Aa"_L1);
+    const bool localeUses12h = amPm >= 0;
+    const bool use12h = use24hFormat == Qt::Unchecked || (use24hFormat == Qt::PartiallyChecked && localeUses12h);
+
+    if (localeUses12h && !use12h) {
+        // Drop the AM/PM field ("A", "Ap", "AP"...) and the space between it and the time
+        qsizetype from = amPm;
+        qsizetype to = amPm + 1;
+        if (to < result.size() && (result[to] == u'p' || result[to] == u'P')) {
+            ++to;
+        }
+        if (amPm > findField(result, "hH"_L1)) {
+            while (from > 0 && result[from - 1].isSpace()) {
+                --from;
+            }
+        } else {
+            while (to < result.size() && result[to].isSpace()) {
+                ++to;
+            }
+        }
+        result.remove(from, to - from);
+    }
+
+    const qsizetype hours = findField(result, "hH"_L1);
+    if (hours < 0) {
+        return format;
+    }
+    const qsizetype hoursEnd = fieldEnd(result, hours);
+    if (localeUses12h && !use12h) {
+        // A 12-hour locale has no convention for 24-hour times: zero-pad them like most 24-hour locales do
+        result.replace(hours, hoursEnd - hours, u"hh"_s);
+    } else {
+        // "H" counts 0-23 even with AM/PM, "h" follows the AM/PM field
+        for (qsizetype i = hours; i < hoursEnd; ++i) {
+            result[i] = u'h';
+        }
+    }
+
+    if (use12h && !localeUses12h) {
+        // The locale has no place for AM/PM: put it right after the time
+        const qsizetype minutes = findField(result, "m"_L1, hours);
+        qsizetype timeEnd = minutes < 0 ? hoursEnd : fieldEnd(result, minutes);
+        const qsizetype seconds = findField(result, "s"_L1, timeEnd);
+        if (seconds >= 0) {
+            timeEnd = fieldEnd(result, seconds);
+        }
+        result.insert(timeEnd, " AP"_L1);
+    }
+
+    return result;
+}
+
+QString TimeFormat::withSeconds(const QString &format, bool seconds)
+{
+    const qsizetype hours = findField(format, "hH"_L1);
+    const qsizetype minutes = findField(format, "m"_L1, hours);
+    if (hours < 0 || minutes < 0) {
+        return format;
+    }
+    const qsizetype minutesEnd = fieldEnd(format, minutes);
+    const qsizetype secondsPos = findField(format, "s"_L1, minutesEnd);
+
+    QString result = format;
+    if (seconds && secondsPos < 0) {
+        // Use the same separator as between hours and minutes ("h:mm" -> "h:mm:ss")
+        const QStringView separator = QStringView(format).sliced(fieldEnd(format, hours), minutes - fieldEnd(format, hours));
+        result.insert(minutesEnd, separator.toString() + u"ss"_s);
+    } else if (!seconds && secondsPos >= 0) {
+        result.remove(minutesEnd, fieldEnd(format, secondsPos) - minutesEnd);
+    }
+    return result;
+}
+
+#include "moc_timeformat.cpp"
diff --git a/applets/digital-clock/plugin/timeformat.h b/applets/digital-clock/plugin/timeformat.h
new file mode 100644
index 0000000000..df7bc94465
--- /dev/null
+++ b/applets/digital-clock/plugin/timeformat.h
@@ -0,0 +1,33 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QObject>
+#include <QQmlEngine>
+
+/*
+ * QLocale only offers a short and a long time format, and neither follows the
+ * clock's own 12/24-hour and seconds settings. These helpers edit a locale
+ * format in place, so everything else the locale chose (where AM/PM goes,
+ * separators, padding) is kept.
+ */
+class TimeFormat : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+public:
+    explicit TimeFormat(QObject *parent = nullptr);
+
+    // The clock's time format: the locale's short time format with the hour cycle
+    // of use24hFormat (a Qt::CheckState; PartiallyChecked = the locale's) and seconds if withSeconds
+    Q_INVOKABLE static QString clockFormat(int use24hFormat, bool withSeconds);
+
+    static QString withHourCycle(const QString &format, Qt::CheckState use24hFormat);
+    static QString withSeconds(const QString &format, bool seconds);
+};
